const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1400, height: 1600, deviceScaleFactor: 2 });

  const htmlPath = path.resolve(__dirname, 'trade_war_dashboard.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle0' });

  // Wait for Mermaid to render
  await page.waitForTimeout(3000);

  await page.screenshot({
    path: '/app/output/result.png',
    fullPage: true
  });

  await browser.close();
  console.log('Screenshot saved to /app/output/result.png');
})();

